  view.innerHTML=`<div class="view">${pageHead('From the Gears of Resistance bench','Shop Notes','Experiments, discoveries, failures, strange purchases, quick observations, and workbench snapshots.',d.canPublish?`<button class="button" data-action="new-shop-note">+ NEW SHOP NOTE</button>`:'')}
    ${mine?.notes?.some(n=>n.status==='Draft')?`<section class="section"><div class="section-head"><h2>Drafts</h2><p>Only you can see these.</p></div><div class="note-list">${mine.notes.filter(n=>n.status==='Draft').map(shopNoteRow).join('')}</div></section>`:''}
    <section class="section"><div class="section-head"><h2>From the Garage</h2><p>${d.notes.length} published notes</p></div><div class="note-list">${d.notes.map(shopNoteRow).join('')||empty('NOTHING ON THIS BENCH YET','The next Shop Note is still being made.')}</div></section></div>`;
