async function buildLogForm(pid,failure=false){
  if(!requireSignIn())return;
  let projects=[]; if(!pid){try{projects=(await api('/api/projects?mine=1')).projects;}catch(err){return toast(err.message,'error')} if(!projects.length)return projectForm();}
  modal({title:failure?'This Didn’t Work':'Add Build Log Entry',eyebrow:failure?'FAILURE IS USEFUL KNOWLEDGE':'WHAT HAPPENED?',body:`<form id="log-form" class="form-grid">${!pid?`<div class="field full"><label>Project</label><select name="projectId">${projects.map(p=>`<option value="${p.id}">${esc(p.title)}</option>`).join('')}</select></div>`:''}<div class="field"><label>Entry type</label><select name="type">${['Idea','Design','Prototype','Experiment','Test','Failure','Revision','Build','Discovery','Decision','Result','Question'].map(x=>`<option ${failure&&x==='Failure'?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Short title</label><input name="title" value="${failure?'THIS DIDN’T WORK':''}" placeholder="What changed?"></div><div class="field full"><label>${failure?'What were you trying to do? What happened? Why? What next?':'Notebook entry'}</label><textarea name="body" required placeholder="${failure?'Record the broken state before fixing it.':'Measurements, observations, decisions, problems, results…'}"></textarea></div><div class="field full"><div class="form-actions"><span class="autosave-state" id="draft-state"><i></i><b>UNSAVED</b></span><button class="button">ADD TO BUILD LOG</button></div></div></form>`,onOpen:m=>{const f=$('#log-form',m),key=`workshop-draft-log-${pid||'select'}`;restoreDraft(f,key,{});wireAutosave(f,key);f.addEventListener('submit',async e=>{e.preventDefault();const b=Object.fromEntries(new FormData(f)),target=pid||b.projectId;try{await api(`/api/projects/${target}/logs`,{method:'POST',body:JSON.stringify(b)});localStorage.removeItem(key);closeOverlay();toast(failure?'Failure documented. Good.':'Build log updated.');location.hash=`#/projects/${target}`;if(routeParts()[1]===target)renderProject(target);}catch(err){toast(err.message,'error')}});}});
}
