async function startFromCurrent(type,id){
  if(!requireSignIn())return;
  if(type==='Build Along'){
    const d=await api(`/api/build-alongs/${id}`),i=d.item;
    return projectForm({title:'Start My Version',draftKey:`ba-${id}`,defaults:{title:`My ${i?.title||'Build Along'}`,description:`My version of ${i?.title||'this Build Along'}. I am changing: `,stage:'Idea',projectType:'Project',tags:'build-along, community-version',disciplines:(i?.skills||[]).join(', '),materials:(i?.materials||[]).join(', '),tools:(i?.tools||[]).join(', '),firstEntry:'What I plan to keep from the reference build:\n\nWhat I plan to change:\n\nWhy:',entryType:'Idea',parentType:'Build Along',parentId:id}});
  }
  const d=await api(`/api/open-briefs/${id}`),i=d.item;
  projectForm({title:'Respond to Open Brief',draftKey:`brief-${id}`,defaults:{title:'Untitled Brief Response',description:i?.objective||'',stage:'Idea',tags:'open-brief, brief-response',disciplines:(i?.recommendedSkills||[]).join(', '),firstEntry:`My reading of the brief:\n\nConstraint I expect to wrestle with:\n\nFirst experiment:`,entryType:'Idea',parentType:'Open Brief',parentId:id}});
}
async function newBriefResponse(){const d=await api('/api/open-briefs');if(!d.items.length)return toast('There is no open brief right now.','error');return startFromCurrent('Open Brief',d.items[0].id);}

