  const u=d.user,isMine=state.me&&state.me.id===u.id, projects=d.projects||[];
  const active=projects.filter(p=>p.status==='Active'),complete=projects.filter(p=>p.status==='Complete'),paused=projects.filter(p=>['Paused','Abandoned'].includes(p.status)),experiments=projects.filter(p=>p.projectType==='Experiment'||p.tags.includes('experiment'));
