function critiqueResponseForm(id){if(!requireSignIn())return;modal({title:'Structured Critique',eyebrow:'BE SPECIFIC · BE USEFUL · QUESTION THE WORK, NOT THE PERSON',size:'lg',body:`<form id="critique-response-form" class="form-grid"><div class="field full"><label>WHAT WORKS</label><textarea name="works"></textarea></div><div class="field full"><label>WHAT I WOULD QUESTION</label><textarea name="question"></textarea></div><div class="field full"><label>WHAT I WOULD TRY</label><textarea name="tryNext"></textarea></div><div class="field full"><label>QUESTIONS</label><textarea name="questions"></textarea></div><div class="field full"><button class="button">ADD CRITIQUE</button></div></form>`,onOpen:m=>$('#critique-response-form',m).addEventListener('submit',async e=>{e.preventDefault();try{await api(`/api/critiques/${id}/responses`,{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});closeOverlay();toast('Critique added.');renderCritique(id)}catch(err){toast(err.message,'error')}})})}
async function editCritique(id){const {critique:c}=await api(`/api/critiques/${id}`);modal({title:'Edit Critique Request',eyebrow:'KEEP THE REVIEW TARGET CLEAR',size:'lg',body:`<form id="edit-critique-form" class="form-grid"><div class="field"><label>Design state</label><select name="designState">${DESIGN_STATES.map(x=>`<option ${c.design_state===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Status</label><select name="status">${['Open','Closed'].map(x=>`<option ${c.status===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field full"><label>Feedback types</label><input name="feedbackTypes" value="${esc(c.feedback_types.join(', '))}"></div><div class="field full"><label>Review prompt</label><textarea name="prompt" required>${esc(c.prompt)}</textarea></div><div class="field full"><button class="button">SAVE CRITIQUE REQUEST</button></div></form>`,onOpen:m=>$('#edit-critique-form',m).addEventListener('submit',async e=>{e.preventDefault();try{await api(`/api/critiques/${id}`,{method:'PUT',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});closeOverlay();toast('Critique request updated.');renderCritique(id)}catch(err){toast(err.message,'error')}})})}
function liveCard(e){return `<a class="project-card live-card" href="#/live/${esc(e.id)}"><div class="project-visual"><span>${e.event_type==='Project Clinic'?'⌕':e.status==='Live'?'●':'▶'}</span></div><div class="project-body"><div class="kicker-row"><span class="stage-badge">${esc(e.status)}</span><span>${esc(e.event_type)}</span></div><h3>${esc(e.title)}</h3><p>${esc(e.description)}</p><div class="project-footer"><span>${fmtDate(e.starts_at,true)}</span><span>${Number(e.comment_count||0)} shop talk</span></div></div></a>`}
async function renderLive(){setTitle('Live From the Garage');const d=await api('/api/live'),up=d.items.filter(x=>x.status!=='Archived'),archive=d.items.filter(x=>x.status==='Archived');const canEdit=state.me&&['Owner','Administrator','Editor'].includes(state.me.role);view.innerHTML=`<div class="view">${pageHead('LIVE FROM THE GARAGE','Live','Shop streams, Project Clinics, design reviews, teardowns, demos, and guest maker sessions.',`<a class="button-secondary" href="#/clinic">PROJECT CLINIC →</a>${canEdit?'<button class="button" data-action="new-live-event">+ SCHEDULE EVENT</button>':''}`)}<section class="section"><div class="section-head"><h2>On the Calendar</h2><p>${up.length} upcoming / live</p></div><div class="grid projects">${up.map(liveCard).join('')||empty('THE CAMERA IS OFF','The next live bench session will appear here.')}</div></section><section class="section"><div class="section-head"><h2>Archive</h2><p>Recordings stay connected to the work.</p></div><div class="grid projects">${archive.map(liveCard).join('')||empty('NO ARCHIVE YET','Past sessions will collect here.')}</div></section></div>`}
function trustedEmbed(url=''){try{const u=new URL(url);if(['www.youtube.com','youtube.com','www.youtube-nocookie.com'].includes(u.hostname)){let id='';if(u.pathname.startsWith('/watch'))id=u.searchParams.get('v')||'';if(u.pathname.startsWith('/embed/'))id=u.pathname.split('/')[2]||'';if(id)return `https://www.youtube-nocookie.com/embed/${encodeURIComponent(id)}`;}if(u.hostname==='youtu.be'){const id=u.pathname.slice(1);if(id)return `https://www.youtube-nocookie.com/embed/${encodeURIComponent(id)}`;}if(u.hostname==='player.vimeo.com'&&u.pathname.startsWith('/video/'))return u.href;}catch{}return ''}
async function renderLiveEvent(id){const d=await api(`/api/live/${id}`),e=d.event;setTitle(e.title);const canEdit=state.me&&['Owner','Administrator','Editor'].includes(state.me.role),media=e.status==='Archived'?(e.archive_url||e.stream_url):e.stream_url,embed=trustedEmbed(media);view.innerHTML=`<div class="view narrow"><header class="discussion-topic-head"><div class="eyebrow">${esc(e.event_type)} · ${esc(e.status)}</div><h1>${esc(e.title)}</h1><div class="topic-byline">${esc(e.host)} · ${fmtDate(e.starts_at,true)}</div><p>${esc(e.description)}</p>${e.project_id?`<a class="linked-project" href="#/projects/${esc(e.project_id)}">↗ Linked project: ${esc(e.project_title||'Open project')}</a>`:''}<div class="head-actions">${canEdit?`<button class="button-secondary" data-action="edit-live-event" data-id="${esc(e.id)}">EDIT EVENT</button>`:''}</div></header>${media?`<section class="section live-player">${embed?`<iframe src="${esc(embed)}" title="${esc(e.title)}" allow="autoplay; encrypted-media; picture-in-picture" allowfullscreen></iframe>`:`<a class="feature-card" href="${esc(media)}" target="_blank" rel="noopener"><div class="feature-copy"><div class="label">${e.status==='Archived'?'RECORDING':'STREAM'}</div><h3>Open video</h3><p>This event uses an external media host that is not embedded directly.</p></div><div class="feature-art">▶</div></a>`}</section>`:''}<section class="section"><div class="section-head"><h2>${e.status==='Archived'?'Session Discussion':'Live Workshop Talk'}</h2><p>${d.comments.length}</p></div><div class="discussion-replies">${d.comments.map(c=>`<article class="discussion-reply"><div class="reply-avatar">${esc(c.avatar_seed||initials(c.author))}</div><div><div class="reply-head"><strong>${esc(c.author)}</strong><span>${ago(c.created_at)}</span></div><p>${esc(c.body)}</p></div></article>`).join('')||empty('QUIET BENCH','The discussion stays with the event and archive.')}</div>${state.me?`<button class="button" data-action="live-comment" data-id="${esc(e.id)}">+ ADD TO THE DISCUSSION</button>`:'<button class="button" data-action="login">ENTER TO JOIN</button>'}</section></div>`}
async function liveEventForm(existing=null){if(!state.me||!['Owner','Administrator','Editor'].includes(state.me.role))return toast('Editor access required.','error');let projects=[];try{projects=(await api('/api/projects')).projects}catch{};const d=existing||{};modal({title:existing?'Edit Live Event':'Schedule Live Event',eyebrow:'LIVE FROM THE GARAGE',size:'lg',body:`<form id="live-event-form" class="form-grid"><div class="field full"><label>Title</label><input name="title" required value="${esc(d.title||'')}"></div><div class="field"><label>Event type</label><select name="eventType">${['Shop Stream','Project Clinic','Build Along','Design Review','Teardown','Q&A','Workshop Tour','Field Instrument Demo','Guest Maker Session'].map(x=>`<option ${(d.event_type||'Shop Stream')===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Status</label><select name="status">${['Scheduled','Live','Archived','Cancelled'].map(x=>`<option ${(d.status||'Scheduled')===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field full"><label>Description</label><textarea name="description">${esc(d.description||'')}</textarea></div><div class="field"><label>Starts</label><input name="startsAt" type="datetime-local" required value="${d.starts_at?esc(new Date(d.starts_at).toISOString().slice(0,16)):''}"></div><div class="field"><label>Ends · optional</label><input name="endsAt" type="datetime-local" value="${d.ends_at?esc(new Date(d.ends_at).toISOString().slice(0,16)):''}"></div><div class="field full"><label>Related project · optional</label><select name="projectId"><option value="">No linked project</option>${projects.map(p=>`<option value="${p.id}" ${d.project_id===p.id?'selected':''}>${esc(p.title)}</option>`).join('')}</select></div><div class="field full"><label>Stream URL</label><input name="streamUrl" value="${esc(d.stream_url||'')}" placeholder="YouTube or Vimeo URL"></div><div class="field full"><label>Archive URL</label><input name="archiveUrl" value="${esc(d.archive_url||'')}" placeholder="Recording URL once archived"></div><div class="field full"><button class="button">${existing?'SAVE EVENT':'PUT IT ON THE CALENDAR'}</button></div></form>`,onOpen:m=>$('#live-event-form',m).addEventListener('submit',async ev=>{ev.preventDefault();const body=Object.fromEntries(new FormData(ev.currentTarget));for(const k of ['startsAt','endsAt'])if(body[k])body[k]=new Date(body[k]).toISOString();try{const out=await api(existing?`/api/live/${existing.id}`:'/api/live',{method:existing?'PUT':'POST',body:JSON.stringify(body)});closeOverlay();toast(existing?'Live event updated.':'Live event scheduled.');location.hash=`#/live/${existing?.id||out.id}`;renderRoute()}catch(err){toast(err.message,'error')}})})}
