async function renderWallExhibition(id){const d=await api(`/api/wall/${id}`),e=d.item;setTitle(e.title);view.innerHTML=`<div class="view"><header class="wall-title"><div class="eyebrow">THE WALL · CURATED EXHIBITION</div><h1>${esc(e.title)}</h1><p>${esc(e.description)}</p><div class="project-meta-line">Curated by ${esc(e.curator)}${e.starts_at?` · ${fmtDate(e.starts_at,true)}`:''}${e.ends_at?` — ${fmtDate(e.ends_at,true)}`:''}</div>${d.canEdit?`<div class="head-actions deep-only"><button class="button-secondary" data-action="edit-wall" data-id="${esc(e.id)}">EDIT EXHIBITION</button><button class="button" data-action="add-wall-project" data-id="${esc(e.id)}">+ ADD PROJECT</button></div>`:''}</header>${d.projects.length?`<section class="wall-gallery">${d.projects.map((p,i)=>`<article class="wall-piece ${i%5===0?'wide':''}"><a href="#/projects/${esc(p.id)}"><div class="wall-piece-art">${p.coverUrl?`<img src="${esc(p.coverUrl)}" alt="${esc(p.title)}">`:`<span>${esc(p.coverEmoji||'✦')}</span>`}</div><div class="wall-piece-label"><div class="label">${esc(p.stage)} · ${esc(p.owner)}</div><h2>${esc(p.title)}</h2><p>${esc(p.wallCaption||p.description)}</p></div></a>${d.canEdit?`<button class="text-button danger-text deep-only" data-action="remove-wall-project" data-id="${esc(p.id)}" data-wall-id="${esc(e.id)}">REMOVE FROM WALL</button>`:''}</article>`).join('')}</section>`:empty('NOTHING HUNG YET','An empty wall is an invitation, not an error.')}</div>`}
async function editWall(id){const d=await api(`/api/wall/${id}`);wallForm({...d.item,id})}
async function addWallProject(wid){const d=await api('/api/projects');const current=await api(`/api/wall/${wid}`),used=new Set(current.projects.map(p=>p.id)),projects=d.projects.filter(p=>!used.has(p.id));modal({title:'Hang a Project',eyebrow:'THE WALL',size:'sm',body:`<form id="wall-project-form" class="form-grid"><div class="field full"><label>Project</label><select name="projectId">${projects.map(p=>`<option value="${esc(p.id)}">${esc(p.title)} — ${esc(p.owner)}</option>`).join('')}</select></div><div class="field full"><label>Exhibition caption</label><textarea name="caption" placeholder="Why is this work on this wall?"></textarea></div><div class="field full"><button class="button">HANG PROJECT</button></div></form>`,onOpen:m=>$('#wall-project-form',m).addEventListener('submit',async e=>{e.preventDefault();try{await api(`/api/wall/${wid}/items`,{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});closeOverlay();toast('Project hung on The Wall.');renderWallExhibition(wid)}catch(err){toast(err.message,'error')}})})}
async function removeWallProject(wid,pid){if(!confirm('Remove this project from this exhibition? The project itself stays intact.'))return;try{await api(`/api/wall/${wid}/items`,{method:'DELETE',body:JSON.stringify({projectId:pid})});toast('Project removed from this exhibition.');renderWallExhibition(wid)}catch(err){toast(err.message,'error')}}


async function renderTeardownClub(){setTitle('Teardown Club');const d=await api('/api/teardown-club');view.innerHTML=`<div class="view">${pageHead('TAKE IT APART · WRITE DOWN WHAT YOU FIND','Teardown Club','A recurring collaborative reverse-engineering record: mechanisms, circuits, materials, repairability, reusable parts, and the design decisions hiding inside ordinary objects.',d.canEdit?'<button class="button deep-only" data-action="new-teardown-club">+ NEW TEARDOWN</button>':'')}<div class="grid projects">${d.items.map(t=>`<a class="project-card" href="#/teardown/${esc(t.id)}"><div class="project-visual"><span>⌖</span></div><div class="project-body"><div class="kicker-row"><span class="stage-badge">${esc(t.status)}</span><span>${esc(t.object_name||'Teardown')}</span></div><h3>${esc(t.title)}</h3><p>${esc(t.overview)}</p><div class="project-footer"><span>${Number(t.contribution_count)} contributions</span><span>${esc(t.curator)}</span></div></div></a>`).join('')||empty('NOTHING ON THE TEARDOWN BENCH','Pick an object worth understanding.')}</div></div>`}
async function renderTeardown(id){const d=await api(`/api/teardown-club/${id}`),t=d.item;setTitle(t.title);view.innerHTML=`<div class="view narrow"><header class="project-header"><div class="eyebrow">TEARDOWN CLUB · ${esc(t.status)}</div><h1>${esc(t.title)}</h1><p class="project-description">${esc(t.overview)}</p><div class="project-meta-line">Curated by ${esc(t.curator)}${t.starts_at?` · ${fmtDate(t.starts_at,true)}`:''}</div><div class="head-actions">${state.me?`<button class="button" data-action="teardown-contribution" data-id="${esc(t.id)}">+ ADD FINDING</button>`:'<button class="button" data-action="login">ENTER TO CONTRIBUTE</button>'}${d.canEdit?`<button class="button-secondary deep-only" data-action="edit-teardown-club" data-id="${esc(t.id)}">EDIT TEARDOWN</button>`:''}</div></header>${t.safety_notes?`<section class="safety-card"><strong>SAFETY NOTES</strong><p>${esc(t.safety_notes)}</p></section>`:''}${t.project_id?`<p><a class="linked-project" href="#/projects/${esc(t.project_id)}">↗ ${esc(t.project_title||'Linked project')}</a></p>`:''}<section class="section"><div class="section-head"><h2>Collaborative Teardown Record</h2><p>${d.contributions.length} findings</p></div>${d.contributions.length?`<div class="note-list">${d.contributions.map(c=>`<article class="note-row teardown-note"><div class="row-meta">${esc(c.category)}<br>${esc(c.author)}<br>${ago(c.created_at)}</div><div class="row-content"><strong>${esc(c.title)}</strong><p>${esc(c.body)}</p><div class="notebook-details">${detailText('Component',c.component)}${detailText('Material',c.material)}${detailText('Mechanism',c.mechanism_notes)}${detailText('Circuit',c.circuit_notes)}${detailText('Repairability',c.repairability)}${detailText('Reusable parts',c.reusable_parts)}</div>${c.photo_urls?.length?`<div class="mystery-photos">${c.photo_urls.map(u=>`<img src="${esc(u)}" alt="Teardown evidence">`).join('')}</div>`:''}</div></article>`).join('')}</div>`:empty('NO FINDINGS YET','Open it carefully and record the first useful observation.')}</section></div>`}
function teardownForm(existing=null){if(!requireSignIn())return;const t=existing||{};api('/api/projects').then(p=>modal({title:existing?'Edit Teardown':'New Teardown Club',eyebrow:'COLLABORATIVE REVERSE ENGINEERING',size:'lg',body:`<form id="teardown-form" class="form-grid"><div class="field full"><label>Title</label><input name="title" required value="${esc(t.title||'')}"></div><div class="field"><label>Object</label><input name="objectName" value="${esc(t.object_name||'')}"></div><div class="field"><label>Status</label><select name="status">${['Active','Complete','Archived'].map(x=>`<option ${t.status===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field full"><label>Overview</label><textarea name="overview">${esc(t.overview||'')}</textarea></div><div class="field full"><label>Safety notes</label><textarea name="safetyNotes">${esc(t.safety_notes||'')}</textarea></div><div class="field"><label>Visibility</label><select name="visibility"><option ${t.visibility!=='Members'?'selected':''}>Public</option><option ${t.visibility==='Members'?'selected':''}>Members</option></select></div><div class="field"><label>Linked project · optional</label><select name="projectId"><option value="">None</option>${p.projects.map(x=>`<option value="${x.id}" ${t.project_id===x.id?'selected':''}>${esc(x.title)}</option>`).join('')}</select></div><div class="field"><label>Starts</label><input type="date" name="startsAt" value="${esc((t.starts_at||'').slice(0,10))}"></div><div class="field"><label>Ends</label><input type="date" name="endsAt" value="${esc((t.ends_at||'').slice(0,10))}"></div><div class="field full"><label>Reference URL · optional</label><input name="referenceUrl" value="${esc(t.reference_url||'')}"></div><div class="field full"><button class="button">${existing?'SAVE TEARDOWN':'OPEN TEARDOWN'}</button></div></form>`,onOpen:m=>$('#teardown-form',m).addEventListener('submit',async e=>{e.preventDefault();try{const out=await api(existing?`/api/teardown-club/${existing.id}`:'/api/teardown-club',{method:existing?'PUT':'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});closeOverlay();toast(existing?'Teardown updated.':'Teardown Club opened.');location.hash=`#/teardown/${existing?.id||out.id}`}catch(err){toast(err.message,'error')}})})).catch(err=>toast(err.message,'error'))}
async function editTeardown(id){const d=await api(`/api/teardown-club/${id}`);teardownForm({...d.item,id})}
function teardownContributionForm(id){if(!requireSignIn())return;modal({title:'Add a Teardown Finding',eyebrow:'OBSERVE · DOCUMENT · EXPLAIN',size:'lg',body:`<form id="tdc-form" class="form-grid"><div class="field"><label>Type</label><select name="category">${['Observation','Mechanism','Component','Circuit','Material','Repairability','Reusable Part','Design Decision'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label>Short title</label><input name="title" required></div><div class="field full"><label>What did you find?</label><textarea name="body" required></textarea></div><div class="field"><label>Component</label><input name="component"></div><div class="field"><label>Material</label><input name="material"></div><div class="field full deep-only"><label>Mechanism notes</label><textarea name="mechanismNotes"></textarea></div><div class="field full deep-only"><label>Circuit notes</label><textarea name="circuitNotes"></textarea></div><div class="field full"><label>Repairability observation</label><textarea name="repairability"></textarea></div><div class="field full"><label>Reusable parts</label><input name="reusableParts"></div><div class="field full"><label>Photo URLs · one per line</label><textarea name="photoUrls"></textarea></div><div class="field full"><button class="button">ADD TO TEARDOWN RECORD</button></div></form>`,onOpen:m=>$('#tdc-form',m).addEventListener('submit',async e=>{e.preventDefault();try{await api(`/api/teardown-club/${id}/contributions`,{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});closeOverlay();toast('Finding added to the teardown record.');renderTeardown(id)}catch(err){toast(err.message,'error')}})})}

async function renderScrapBin(){setTitle('Scrap Bin');const d=await api('/api/scrap-bin');view.innerHTML=`<div class="view">${pageHead('KEEP USEFUL THINGS OUT OF THE TRASH','Scrap Bin','Free, trade, shipping-cost, and local-pickup reuse between members. No storefronts. No bidding. No checkout.',state.me?'<button class="button" data-action="new-scrap">+ OFFER SOMETHING</button>':'<button class="button" data-action="login">ENTER TO OFFER</button>')}<div class="scrap-principle">Approximate city/region only. Arrange exchange details privately. THE WORKSHOP does not process payment.</div><div class="grid projects">${d.items.map(x=>`<a class="project-card" href="#/scrap/${esc(x.id)}"><div class="project-visual"><span>♲</span></div><div class="project-body"><div class="kicker-row"><span class="stage-badge">${esc(x.exchange_type)}</span><span>${esc(x.category)}</span></div><h3>${esc(x.title)}</h3><p>${esc(x.description)}</p><div class="project-footer"><span>${esc(x.city_region||'Region not listed')}</span><span>${esc(x.owner)}</span></div></div></a>`).join('')||empty('THE BIN IS EMPTY','That is probably a temporary victory.')}</div></div>`}
async function renderScrapListing(id){const d=await api(`/api/scrap-bin/${id}`),x=d.item;setTitle(x.title);view.innerHTML=`<div class="view narrow"><header class="project-header"><div class="eyebrow">SCRAP BIN · ${esc(x.status)}</div><h1>${esc(x.title)}</h1><div class="project-meta-line">${esc(x.owner)} · ${esc(x.city_region||'Region not listed')} · ${esc(x.exchange_type)}</div><p class="project-description">${esc(x.description)}</p><div class="head-actions">${d.isOwner?`<button class="button-secondary" data-action="edit-scrap" data-id="${esc(x.id)}">EDIT LISTING</button>`:state.me&&x.status==='Available'?`<button class="button" data-action="scrap-inquiry" data-id="${esc(x.id)}">I'M INTERESTED</button>`:' '}</div></header>${x.image_url?`<img class="scrap-image" src="${esc(x.image_url)}" alt="${esc(x.title)}">`:''}<section class="section"><div class="notebook-details">${detailText('Category',x.category)}${detailText('Exchange',x.exchange_type)}${detailText('Quantity',x.quantity_text)}${detailText('Condition',x.condition_text)}${detailText('Approximate location',x.city_region)}</div></section>${d.myInquiry?`<section class="detail-card"><h3>Your inquiry</h3><p>${esc(d.myInquiry.message)}</p><span class="tag">${esc(d.myInquiry.status)}</span></section>`:''}${d.isOwner?`<section class="section"><div class="section-head"><h2>Inquiries</h2><p>${d.inquiries.length}</p></div>${d.inquiries.length?d.inquiries.map(i=>`<article class="note-card"><strong>${esc(i.sender)}</strong><p>${esc(i.message)}</p><div class="head-actions"><span class="tag">${esc(i.status)}</span>${i.status==='Open'?`<button class="text-button" data-action="scrap-inquiry-status" data-id="${esc(i.id)}" data-listing-id="${esc(x.id)}" data-status="Closed">CLOSE INQUIRY</button>`:''}</div></article>`).join(''):empty('NO INQUIRIES YET','The listing is available to the Workshop.')}</section>`:''}</div>`}
function scrapForm(existing=null){if(!requireSignIn())return;const x=existing||{};modal({title:existing?'Edit Scrap Listing':'Offer Something',eyebrow:'SCRAP BIN · REUSE BOARD',size:'lg',body:`<form id="scrap-form" class="form-grid"><div class="field full"><label>What is it?</label><input name="title" required value="${esc(x.title||'')}"></div><div class="field"><label>Category</label><select name="category">${['motors','gears','electronics','sheet material','test equipment','hardware','machine parts','fabric','lumber','unusual components','Other'].map(v=>`<option ${x.category===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>Exchange</label><select name="exchangeType">${['Free','Trade','Cost of Shipping','Local Pickup'].map(v=>`<option ${x.exchange_type===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field full"><label>Description</label><textarea name="description">${esc(x.description||'')}</textarea></div><div class="field"><label>City / region only</label><input name="cityRegion" value="${esc(x.city_region||'')}"></div><div class="field"><label>Status</label><select name="status">${['Available','Claimed','Gone'].map(v=>`<option ${x.status===v?'selected':''}>${v}</option>`).join('')}</select></div><div class="field"><label>Quantity</label><input name="quantityText" value="${esc(x.quantity_text||'')}"></div><div class="field"><label>Condition</label><input name="conditionText" value="${esc(x.condition_text||'')}"></div><div class="field full"><label>Image URL · optional</label><input name="imageUrl" value="${esc(x.image_url||'')}"></div><div class="field full"><button class="button">${existing?'SAVE LISTING':'PUT IN SCRAP BIN'}</button></div></form>`,onOpen:m=>$('#scrap-form',m).addEventListener('submit',async e=>{e.preventDefault();try{const out=await api(existing?`/api/scrap-bin/${existing.id}`:'/api/scrap-bin',{method:existing?'PUT':'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});closeOverlay();toast(existing?'Listing updated.':'Added to the Scrap Bin.');location.hash=`#/scrap/${existing?.id||out.id}`}catch(err){toast(err.message,'error')}})})}
async function editScrap(id){const d=await api(`/api/scrap-bin/${id}`);scrapForm({...d.item,id})}
function scrapInquiryForm(id){if(!requireSignIn())return;modal({title:"I'm Interested",eyebrow:'SCRAP BIN · PRIVATE INQUIRY',size:'sm',body:`<form id="scrap-inquiry-form" class="form-grid"><div class="field full"><label>Message to the member</label><textarea name="message" required placeholder="What would you like to reuse it for? Ask about exchange or pickup details here."></textarea></div><div class="field full"><button class="button">SEND INQUIRY</button></div></form>`,onOpen:m=>$('#scrap-inquiry-form',m).addEventListener('submit',async e=>{e.preventDefault();try{await api(`/api/scrap-bin/${id}/inquiries`,{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});closeOverlay();toast('Inquiry sent privately.');renderScrapListing(id)}catch(err){toast(err.message,'error')}})})}
async function scrapInquiryStatus(id,status,listingId){try{await api(`/api/scrap-inquiries/${id}`,{method:'PUT',body:JSON.stringify({status})});toast('Inquiry updated.');renderScrapListing(listingId)}catch(err){toast(err.message,'error')}}


